<?php
declare(strict_types=1);
require_once __DIR__.'/config/auth.php';
$reviewerId=require_roles(['Administrator','Staff']);
require_once __DIR__.'/config/db.php';
function prh($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function prm($v):string{return '₱'.number_format((float)$v,2);}
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_var($_POST['payment_id']??0,FILTER_VALIDATE_INT);$decision=$_POST['decision']??'';$note=trim((string)($_POST['review_note']??''));
 if(!$id||!in_array($decision,['approve','reject'],true))$error='Invalid payment review request.';
 else try{
  $conn->begin_transaction();$stmt=$conn->prepare("SELECT id,payment_type,reservation_id,auction_id,property_id,user_id,amount,status FROM checkout_payments WHERE id=? FOR UPDATE");$stmt->bind_param('i',$id);$stmt->execute();$pay=$stmt->get_result()->fetch_assoc();$stmt->close();
  if(!$pay||$pay['status']!=='pending')throw new RuntimeException('This payment has already been reviewed or does not exist.');
  if($decision==='approve'){
   if($pay['payment_type']==='reservation'){$stmt=$conn->prepare("UPDATE properties SET status='Reserved' WHERE id=? AND status='Available'");$stmt->bind_param('i',$pay['property_id']);$stmt->execute();$ok=$stmt->affected_rows===1;$stmt->close();if(!$ok)throw new RuntimeException('The property is no longer available. Resolve the reservation manually before approving.');$stmt=$conn->prepare("UPDATE reservations SET status='Approved' WHERE id=? AND status='Pending'");$stmt->bind_param('i',$pay['reservation_id']);$stmt->execute();$stmt->close();}
   else{$stmt=$conn->prepare("UPDATE properties SET status='Sold' WHERE id=? AND status IN ('Auction','Available')");$stmt->bind_param('i',$pay['property_id']);$stmt->execute();$ok=$stmt->affected_rows===1;$stmt->close();if(!$ok)throw new RuntimeException('The property status could not be updated. Review it manually before approving.');}
   $newStatus='paid';
  }else{$newStatus='failed';if($pay['reservation_id']){$stmt=$conn->prepare("UPDATE reservations SET status='Cancelled' WHERE id=? AND status='Pending'");$stmt->bind_param('i',$pay['reservation_id']);$stmt->execute();$stmt->close();}}
  $stmt=$conn->prepare("UPDATE checkout_payments SET status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE id=? AND status='pending'");$stmt->bind_param('sisi',$newStatus,$reviewerId,$note,$id);$stmt->execute();$stmt->close();
  $title=$decision==='approve'?'Payment approved':'Payment proof needs attention';$message=$decision==='approve'?'Your HomeBid payment was verified. Your receipt is now available.':('Your payment proof was not approved. '.($note!==''?$note:'Please contact HomeBid staff for details.'));$entity='payment';
  $stmt=$conn->prepare("INSERT INTO notifications(user_id,title,message,related_entity,related_id) VALUES(?,?,?,?,?)");$stmt->bind_param('ssssi',$pay['user_id'],$title,$message,$entity,$id);$stmt->execute();$stmt->close();
  $action=$decision==='approve'?'Approved manual payment':'Rejected manual payment';$type='payment';$ip=$_SERVER['REMOTE_ADDR']??null;$stmt=$conn->prepare("INSERT INTO activity_logs(user_id,action,entity_type,record_id,ip_address) VALUES(?,?,?,?,?)");$stmt->bind_param('issis',$reviewerId,$action,$type,$id,$ip);$stmt->execute();$stmt->close();$conn->commit();$notice=$decision==='approve'?'Payment approved. A receipt is now available.':'Payment rejected. The buyer has been notified.';
 }catch(Throwable $e){try{$conn->rollback();}catch(Throwable $ignored){}$error=$e instanceof RuntimeException?$e->getMessage():'The payment could not be updated. Check the database migration.';error_log('HomeBid payment review: '.$e->getMessage());}
}
$rows=hb_fetch_all(hb_query($conn,"SELECT cp.*,p.title,u.username,u.email FROM checkout_payments cp JOIN properties p ON p.id=cp.property_id JOIN users u ON u.id=cp.user_id WHERE cp.status='pending' AND cp.proof_path IS NOT NULL ORDER BY cp.created_at ASC"));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment verification | HomeBid</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7f8;color:#17212b;font:14px Arial,sans-serif}.wrap{max-width:1200px;margin:auto;padding:26px 16px}.top{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:20px}.panel{background:#fff;border:1px solid #e1e7ea;border-radius:12px;padding:18px;margin-bottom:14px}.muted{color:#687783}.notice{padding:12px;background:#eaf8ef;color:#17643a;border-radius:8px}.error{padding:12px;background:#fff0ef;color:#a12622;border-radius:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}button,a{padding:10px 14px;border:0;border-radius:8px;text-decoration:none;font-weight:700;cursor:pointer}a{background:#e8edf0;color:#17212b}.approve{background:#17643a;color:#fff}.reject{background:#a12622;color:#fff}textarea{width:100%;min-height:64px;padding:10px;border:1px solid #ccd5da;border-radius:8px;font:inherit}@media(max-width:700px){.grid{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><header class="top"><div><p class="muted">HOMEBID MANAGEMENT</p><h1>Payment verification</h1><p class="muted">Review uploaded GCash or bank-transfer proof before marking a payment as paid.</p></div><a href="<?=($_SESSION['role']??'')==='Administrator'?'admin/dashboard.php':'staff/staff_dashboard.php'?>">Back to dashboard</a></header>
<?php if($notice):?><p class="notice"><?=prh($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=prh($error)?></p><?php endif;?>
<?php if(!$rows):?><section class="panel">There are no payment submissions awaiting review.</section><?php endif;?>
<?php foreach($rows as $r):?><section class="panel"><div class="grid"><div><h2><?=prh($r['title'])?></h2><p><b><?=prh($r['username'])?></b> · <?=prh($r['email'])?></p><p>Type: <?=prh(ucfirst($r['payment_type']))?> · Method: <?=prh($r['payment_method']??'Manual transfer')?> · Amount: <b><?=prm($r['amount'])?></b></p><p>Submitted: <?=prh(date('M j, Y g:i a',strtotime($r['created_at'])))?></p><p>Reference: <?=prh($r['external_id'])?></p><a href="payment-proof.php?id=<?=(int)$r['id']?>" target="_blank" rel="noopener">Open uploaded proof</a></div><div><p><b>Review decision</b></p><form method="post"><input type="hidden" name="csrf_token" value="<?=prh(csrf_token())?>"><input type="hidden" name="payment_id" value="<?=(int)$r['id']?>"><textarea name="review_note" placeholder="Optional note for the buyer"></textarea><div class="actions"><button class="approve" name="decision" value="approve" onclick="return confirm('Verify this payment and issue the receipt?')">Approve payment</button><button class="reject" name="decision" value="reject" onclick="return confirm('Reject this payment proof?')">Reject proof</button></div></form></div></div></section><?php endforeach;?></main></body></html>